// Helper to generate full house structure from planet-specific core profiles
function createPlanetHouses(core) {
  const houses = {};
  for (let h = 1; h <= 12; h++) {
    houses[h] = {
      positive: core.positive.replace('{H}', h),
      neutral: core.neutral.replace('{H}', h),
      negative: core.negative.replace('{H}', h)
    };
  }
  return houses;
}

